SRC = "/Users/urij/Desktop/ChatExport_2026-09-29/result.json"
OUT = sys.argv[1]
NAMES = {"Юрий Аксенов": "Юра", "Polina Starova": "Полина"}
SESSION_GAP_MIN = 60

def flat_text(t):
    if isinstance(t, str):
        return t
    return "".join(p if isinstance(p, str) else p.get("text", "") for p in t)

def describe(m):
    parts = []
    mt = m.get("media_type")
    if mt == "sticker":
        parts.append(f"<стикер {m.get('sticker_emoji','')}>")
    elif mt == "voice_message":
        parts.append(f"<голосовое {m.get('duration_seconds','?')} сек>")
    elif mt == "video_message":
        parts.append(f"<видео-кружок {m.get('duration_seconds','?')} сек>")
    elif mt == "video_file":
        parts.append(f"<видео {m.get('duration_seconds','?')} сек>")
    elif mt == "animation":
        parts.append("<gif>")
    elif mt:
        parts.append(f"<{mt}>")
    if m.get("photo"):
        parts.append("<фото>")
    if m.get("file") and not mt:
        parts.append(f"<файл {m.get('file_name','')}>")
    if m.get("forwarded_from"):
        parts.append(f"<переслано от: {m['forwarded_from']}>")
    return " ".join(parts)

d = json.load(open(SRC, encoding="utf-8"))
msgs = [m for m in d["messages"] if m.get("type") == "message"]
rows = []
for m in msgs:
    text = flat_text(m.get("text", "")).strip()
    who = NAMES.get(m.get("from"), m.get("from"))
    dt = datetime.fromisoformat(m["date"])
    reactions = []
    for r in m.get("reactions", []) or []:
        emoji = r.get("emoji") or r.get("document_id") or "?"
        by = [NAMES.get(x.get("from"), x.get("from")) for x in r.get("recent", [])]
        reactions.append(f"{emoji} от {', '.join(by) if by else '?'}")
    rows.append(dict(id=m["id"], dt=dt, who=who, text=text, extra=describe(m),
                     reply=m.get("reply_to_message_id"), edited=bool(m.get("edited")),
                     reactions=reactions))

def line(r):
    s = f"[{r['id']}] {r['dt'].strftime('%d.%m %a %H:%M')} {r['who']}"
    if r["reply"]:
        s += f" (ответ на [{r['reply']}])"
    s += ": "
    body = " ".join(x for x in [r["extra"], r["text"]] if x)
    s += body.replace("\n", " ⏎ ")
    if r["reactions"]:
        s += "   {реакции: " + "; ".join(r["reactions"]) + "}"
    return s

# full transcript + per-day files
by_day = collections.OrderedDict()
for r in rows:
    by_day.setdefault(r["dt"].strftime("%Y-%m-%d"), []).append(r)

with open(os.path.join(OUT, "transcript.txt"), "w", encoding="utf-8") as f:
    prev = None
    for day, rs in by_day.items():
        f.write(f"\n===== {day} ({rs[0]['dt'].strftime('%A')}) — сообщений: {len(rs)} =====\n")
        for r in rs:
            if prev and (r["dt"] - prev).total_seconds() > SESSION_GAP_MIN * 60:
                gap = r["dt"] - prev
                f.write(f"    --- пауза {int(gap.total_seconds()//3600)} ч {int(gap.total_seconds()%3600//60)} мин ---\n")
            f.write(line(r) + "\n")
            prev = r["dt"]

# stats
def med(xs):
    return round(statistics.median(xs), 1) if xs else None

stats = {"total": len(rows), "by_author": collections.Counter(r["who"] for r in rows)}
chars = collections.defaultdict(list)
questions = collections.Counter()
for r in rows:
    chars[r["who"]].append(len(r["text"]))
    if "?" in r["text"]:
        questions[r["who"]] += 1
stats["chars_total"] = {k: sum(v) for k, v in chars.items()}
stats["chars_median"] = {k: med(v) for k, v in chars.items()}
stats["chars_mean"] = {k: round(sum(v)/len(v), 1) for k, v in chars.items()}
stats["msgs_with_question"] = dict(questions)

# sessions: split by gap
sessions = []
cur = [rows[0]]
for a, b in zip(rows, rows[1:]):
    if (b["dt"] - a["dt"]).total_seconds() > SESSION_GAP_MIN * 60:
        sessions.append(cur); cur = []
    cur.append(b)
sessions.append(cur)
stats["sessions"] = len(sessions)
stats["session_started_by"] = dict(collections.Counter(s[0]["who"] for s in sessions))
stats["session_ended_by"] = dict(collections.Counter(s[-1]["who"] for s in sessions))

# response times on turn switches (within same session)
resp = collections.defaultdict(list)
for a, b in zip(rows, rows[1:]):
    if a["who"] != b["who"]:
        resp[b["who"]].append((b["dt"] - a["dt"]).total_seconds() / 60)
stats["reply_minutes_median"] = {k: med(v) for k, v in resp.items()}
stats["reply_minutes_p90"] = {k: round(sorted(v)[int(len(v)*0.9)], 1) for k, v in resp.items()}
stats["reply_over_3h"] = {k: sum(1 for x in v if x > 180) for k, v in resp.items()}

# reactions given
rg = collections.Counter()
for r in rows:
    for x in r["reactions"]:
        by = x.split(" от ")[-1]
        rg[by] += 1
stats["reactions_given"] = dict(rg)
stats["media"] = {}
for r in rows:
    if r["extra"]:
        stats["media"].setdefault(r["who"], collections.Counter())[r["extra"].split()[0]] += 1
stats["media"] = {k: dict(v) for k, v in stats["media"].items()}

# per-day table
days = []
for day, rs in by_day.items():
    c = collections.Counter(r["who"] for r in rs)
    ch = collections.Counter()
    for r in rs:
        ch[r["who"]] += len(r["text"])
    first = rs[0]
    hours = sorted({r["dt"].hour for r in rs})
    days.append(dict(day=day, weekday=first["dt"].strftime("%a"), total=len(rs),
                     yura=c.get("Юра", 0), polina=c.get("Полина", 0),
                     yura_chars=ch.get("Юра", 0), polina_chars=ch.get("Полина", 0),
                     first_by=first["who"], first_at=first["dt"].strftime("%H:%M"),
                     last_by=rs[-1]["who"], last_at=rs[-1]["dt"].strftime("%H:%M"),
                     first_id=rs[0]["id"], last_id=rs[-1]["id"]))
stats["days"] = days
hours = collections.defaultdict(collections.Counter)
for r in rows:
    hours[r["who"]][r["dt"].hour] += 1
stats["hours"] = {k: dict(sorted(v.items())) for k, v in hours.items()}
stats["by_author"] = dict(stats["by_author"])
json.dump(stats, open(os.path.join(OUT, "stats.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)

print("transcript chars:", os.path.getsize(os.path.join(OUT, "transcript.txt")))
for k in ["total","by_author","chars_total","chars_median","chars_mean","msgs_with_question","sessions",
          "session_started_by","session_ended_by","reply_minutes_median","reply_minutes_p90","reply_over_3h",
          "reactions_given","media"]:
    print(k, "=", stats[k])
print()
print("day        wd  total  Ю   П   Ю_зн  П_зн  начал(когда)  закончил(когда)  ids")
for x in days:
    print(x["day"], x["weekday"], f"{x['total']:>5}", f"{x['yura']:>4}", f"{x['polina']:>4}", f"{x['yura_chars']:>6}", f"{x['polina_chars']:>6}",
          f"  {x['first_by']} {x['first_at']}", f"  {x['last_by']} {x['last_at']}", f"  {x['first_id']}-{x['last_id']}")
print()
for k, v in stats["hours"].items():
    print(k, v)
