"""Verify that every {id, quote} pair in a JSON result, and every «quote» [id] pair in a markdown report,
matches the real message text in the Telegram export."""
import json, re, sys
SRC = "/Users/urij/Desktop/ChatExport_2026-09-29/result.json"
def flat(t):
    return t if isinstance(t, str) else "".join(p if isinstance(p, str) else p.get("text", "") for p in t)
def norm(s):
    s = s.lower().replace("ё", "е").replace("⏎", " ")
    s = re.sub(r"[«»\"'“”„…]", "", s)
    s = re.sub(r"\.\.\.", "", s)
    return re.sub(r"\s+", " ", s).strip()
msgs = {m["id"]: m for m in json.load(open(SRC, encoding="utf-8"))["messages"]}
text = {i: norm(flat(m.get("text", ""))) for i, m in msgs.items()}
who = {i: m.get("from") for i, m in msgs.items()}

def check(i, q):
    if i not in text: return "нет такого id"
    nq = norm(q)
    if not nq: return "пустая цитата"
    if nq in text[i]: return None
    # allow quotes stitched with ellipsis: every part must be present
    parts = [p for p in re.split(r"\s*(?:\[\.\.\.\]|\.\.\.|…)\s*", q) if norm(p)]
    if len(parts) > 1 and all(norm(p) in text[i] for p in parts): return None
    # maybe quote belongs to a neighbour id
    for j in text:
        if abs(j - i) <= 40 and nq in text[j]: return f"цитата из соседнего сообщения [{j}]"
    for j in text:
        if nq in text[j]: return f"цитата из другого сообщения [{j}]"
    return "текст не найден"

def walk(o, path, out):
    if isinstance(o, dict):
        if "id" in o and "quote" in o and isinstance(o["id"], int):
            out.append((path, o["id"], o["quote"]))
        for k, v in o.items(): walk(v, f"{path}.{k}", out)
    elif isinstance(o, list):
        for n, v in enumerate(o): walk(v, f"{path}[{n}]", out)

mode, path = sys.argv[1], sys.argv[2]
bad = total = 0
if mode == "json":
    pairs = []; walk(json.load(open(path, encoding="utf-8")), "", pairs)
    for p, i, q in pairs:
        total += 1; r = check(i, q)
        if r: bad += 1; print(f"ПЛОХО {p} [{i}] {q!r} -> {r}")
else:
    md = open(path, encoding="utf-8").read()
    for m in re.finditer(r"«([^»]{3,300})»[^\[\n]{0,60}\[(\d{6})\]", md):
        total += 1; q, i = m.group(1), int(m.group(2)); r = check(i, q)
        if r: bad += 1; print(f"ПЛОХО [{i}] «{q}» -> {r}")
    for m in re.finditer(r"\[(\d{6})\][^«\n]{0,40}«([^»]{3,300})»", md):
        total += 1; i, q = int(m.group(1)), m.group(2); r = check(i, q)
        if r: bad += 1; print(f"ПЛОХО(id перед цитатой) [{i}] «{q}» -> {r}")
    ids = {int(x) for x in re.findall(r"\[(\d{6})\]", md)}
    print("id в отчёте, которых нет в экспорте:", sorted(i for i in ids if i not in text))
print(f"проверено пар: {total}, с проблемой: {bad}")
